import mongoose,{Schema} from 'mongoose';
export const Branch=mongoose.model('Branch',new Schema({name:{type:String,required:true},address:String,phone:String,active:{type:Boolean,default:true}},{timestamps:true}));
export const Table=mongoose.model('Table',new Schema({name:{type:String,required:true,index:true},area:{type:String,default:'Indoor'},capacity:{type:Number,default:4},status:{type:String,enum:['available','occupied','reserved','cleaning','blocked'],default:'available'},guests:{type:Number,default:0},waiter:{type:Schema.Types.ObjectId,ref:'User'},seatedAt:Date,branch:{type:Schema.Types.ObjectId,ref:'Branch'}},{timestamps:true}));
export const Customer=mongoose.model('Customer',new Schema({name:{type:String,required:true},phone:{type:String,index:true},email:String,address:String,deliveryAddresses:[String],notes:String,loyaltyPoints:{type:Number,default:0},totalSpent:{type:Number,default:0}},{timestamps:true}));
export const Supplier=mongoose.model('Supplier',new Schema({name:{type:String,required:true,index:true},contact:String,email:String,address:String,outstandingBalance:{type:Number,default:0}},{timestamps:true}));
export const Expense=mongoose.model('Expense',new Schema({category:{type:String,required:true},date:{type:Date,default:Date.now},amount:{type:Number,required:true,min:0},paymentMethod:String,note:String,branch:{type:Schema.Types.ObjectId,ref:'Branch'},createdBy:{type:Schema.Types.ObjectId,ref:'User'}},{timestamps:true}));
export const Purchase=mongoose.model('Purchase',new Schema({number:{type:String,index:true},supplier:{type:Schema.Types.ObjectId,ref:'Supplier'},items:[{inventoryItem:{type:Schema.Types.ObjectId,ref:'InventoryItem'},quantity:Number,unitCost:Number,total:Number}],total:{type:Number,default:0},paymentStatus:{type:String,enum:['paid','partial','pending'],default:'pending'},received:{type:Boolean,default:false},date:{type:Date,default:Date.now}},{timestamps:true}));
export const Setting=mongoose.model('Setting',new Schema({key:{type:String,unique:true},value:Schema.Types.Mixed},{timestamps:true}));
